<?php
declare(strict_types=1);
require __DIR__.'/server/lib.php';
try{$id=$_GET['id']??'';if(!is_string($id)||!preg_match('/^(?:fm-)?\d{1,12}$/',$id))throw new RuntimeException('id');$cfg=pp_config();if(!is_file($cfg['storage_dir'].'/player-'.$id.'.json'))throw new RuntimeException('unknown');$file=$cfg['storage_dir'].'/portrait-'.$id.'.png';
 if(!is_file($file)){$miss=$file.'.missing';if(is_file($miss)&&filemtime($miss)>time()-86400)throw new RuntimeException('missing');$cfg['source_hosts']=array_merge($cfg['source_hosts'],['a.espncdn.com','en.wikipedia.org','upload.wikimedia.org','thumb.wikimedia.org']);$cfg['request_timeout_seconds']=3;$cfg['http_user_agent']='WorldOfSimulation/1.0 (https://worldofsimulation.com)';$cfg['max_download_bytes']=600000;try{
  $raw='';$isFotmob=str_starts_with($id,'fm-');if($isFotmob){$cfg['source_hosts'][]='images.fotmob.com';$raw=pp_fetch_raw('https://images.fotmob.com/image_resources/playerimages/'.substr($id,3).'.png',$cfg);}else try{$raw=pp_fetch_raw('https://a.espncdn.com/i/headshots/soccer/players/full/'.$id.'.png',$cfg);}catch(Throwable $e){}
  if(!@getimagesizefromstring($raw)){$entry=pp_read($cfg['storage_dir'].'/player-'.$id.'.json');$year=substr($entry['dateOfBirth']??'',0,4);if(!preg_match('/^\d{4}$/',$year))throw new RuntimeException('portrait identity unavailable');$summary=pp_fetch('https://en.wikipedia.org/api/rest_v1/page/summary/'.rawurlencode(str_replace(' ','_',$entry['name'])),$cfg);$description=(string)($summary['description']??'');if(!preg_match('/footballer|soccer player/i',$description)||!str_contains($description,$year))throw new RuntimeException('portrait identity');$url=explode('?',(string)($summary['thumbnail']['source']??''))[0];$raw=pp_fetch_raw($url,$cfg);pp_write($cfg['storage_dir'].'/portrait-'.$id.'-source.json',['player'=>$entry['name'],'page'=>$summary['content_urls']['desktop']['page']??null,'image'=>$url,'note'=>'Photo used to estimate display colours; not a biometric likeness.']);}
  $size=@getimagesizefromstring($raw);if(!$size||$size[0]>1024||$size[1]>2048)throw new RuntimeException('image');$temp=$file.'.'.bin2hex(random_bytes(4));file_put_contents($temp,$raw,LOCK_EX);rename($temp,$file);}catch(Throwable $e){@touch($miss);throw $e;}}
 $image=getimagesize($file);header('Content-Type: '.($image['mime']??'image/png'));header('X-Content-Type-Options: nosniff');header('Cache-Control: public, max-age=86400');readfile($file);
}catch(Throwable $e){http_response_code(404);header('Cache-Control: public, max-age=600');}
